import type { NetworkId } from "@kawase/networks";

/**
 * What Kawase can do on each network, as shipped (`CAPABILITIES` below is the target gated by what has shipped). A capability can be switched off at runtime per network
 * (`capability_overrides`) without a deploy; the agent reads the merged view before it proposes anything (D15).
 * "coming" is shown to the user as not yet available, "unavailable" is hidden.
 */
export type CapabilityState = "available" | "coming" | "unavailable";

export type CapabilityId =
  | "send"
  | "request"
  | "contacts"
  | "swap"
  | "bridge"
  | "yield"
  | "automations"
  | "marketplace"
  | "voice"
  | "faucet"
  | "payment_links";

/** Where each capability will exist once its stage has shipped (the product plan, not the current build). */
const TARGET: Record<CapabilityId, Record<NetworkId, CapabilityState>> = {
  send: { mainnet: "available", testnet: "available" },
  request: { mainnet: "available", testnet: "available" },
  contacts: { mainnet: "available", testnet: "available" },
  swap: { mainnet: "available", testnet: "available" },
  bridge: { mainnet: "available", testnet: "available" },
  // App Kit Earn lists Morpho vaults on Arc and mock Morpho vaults on Arc Testnet (checked 2026-10-01).
  yield: { mainnet: "available", testnet: "available" },
  automations: { mainnet: "available", testnet: "available" },
  // Circle's x402 catalog has mainnet listings only (D14 research).
  marketplace: { mainnet: "available", testnet: "unavailable" },
  voice: { mainnet: "available", testnet: "available" },
  // Test money is a testnet thing by definition.
  faucet: { mainnet: "unavailable", testnet: "available" },
  payment_links: { mainnet: "available", testnet: "available" },
};

/**
 * The capabilities whose stage has actually shipped. Add an id in the commit that ships it (send in Stage 5,
 * swap and bridge in Stage 6, …). Until then it reports "coming" wherever the target says "available", so
 * neither the app nor the agent is ever told that something unbuilt can be done.
 */
export const SHIPPED_CAPABILITIES: ReadonlySet<CapabilityId> = new Set<CapabilityId>(["faucet", "send", "contacts", "request", "payment_links", "swap", "bridge", "yield", "automations"]);

const shippedState = (id: CapabilityId, state: CapabilityState): CapabilityState =>
  state === "available" && !SHIPPED_CAPABILITIES.has(id) ? "coming" : state;

export const CAPABILITIES = Object.fromEntries(
  (Object.entries(TARGET) as [CapabilityId, Record<NetworkId, CapabilityState>][]).map(([id, byNetwork]) => [
    id,
    { mainnet: shippedState(id, byNetwork.mainnet), testnet: shippedState(id, byNetwork.testnet) },
  ]),
) as Record<CapabilityId, Record<NetworkId, CapabilityState>>;

// Automations (Stage 8): something the person asked Kawase to do on a schedule ("every Tuesday send $1 to Alex"),
// bounded on chain by its own grant (a delegation pinned to the recipient, capped per period) and run by Kawase
// without asking again. Each occurrence is one row, unique per automation and scheduled time, so a run happens at
// most once however often the runner looks; a run that cannot go says why.
import { sql } from "drizzle-orm";
import { index, integer, jsonb, pgEnum, pgTable, text, uniqueIndex, uuid } from "drizzle-orm/pg-core";

import { createdAt, id, networkEnum, timestampTz, updatedAt } from "./common";
import { users } from "./identity";

export const automationStatusEnum = pgEnum("automation_status", ["draft", "active", "paused", "canceled", "ended"]);
export const automationKindEnum = pgEnum("automation_kind", ["scheduled_send"]);
export const automationRunStatusEnum = pgEnum("automation_run_status", ["executing", "succeeded", "skipped", "failed"]);

/** When it runs: every day, week (on a weekday) or month (on a day of the month), at a local time in a time zone. */
export type AutomationSchedule = {
  every: "day" | "week" | "month";
  /** 0 = Sunday … 6 = Saturday, for weekly. */
  weekday?: number | undefined;
  /** 1–28, for monthly. */
  monthday?: number | undefined;
  /** "09:00", local to `timezone`. */
  time: string;
  timezone: string;
};

/** What it does: send exactly this amount of this token to this resolved recipient. */
export type AutomationAction = {
  recipientWords: string;
  recipientAddress: string;
  recipientName: string | null;
  asset: "USDC" | "EURC";
  /** Base units. */
  amount: string;
  note: string | null;
};

export const automations = pgTable(
  "automations",
  {
    id: id(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    network: networkEnum().notNull(),
    kind: automationKindEnum().notNull(),
    status: automationStatusEnum().notNull().default("draft"),
    /** The chat that made it, if any. */
    threadId: uuid(),
    schedule: jsonb().$type<AutomationSchedule>().notNull(),
    action: jsonb().$type<AutomationAction>().notNull(),
    /** The grant that bounds it on chain (set when it is turned on). */
    grantId: uuid(),
    /** The policy report when it was drafted: every check and the one that blocks turning it on. */
    report: jsonb().$type<{ results: unknown[]; blocking: unknown }>(),
    nextRunAt: timestampTz(),
    lastRunAt: timestampTz(),
    /** After this it ends by itself (the grant expires then too). */
    endsAt: timestampTz().notNull(),
    runsDone: integer().notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index("automations_due_idx").on(table.status, table.nextRunAt),
    index("automations_user_idx").on(table.userId, table.network),
  ],
);

export const automationRuns = pgTable(
  "automation_runs",
  {
    id: id(),
    automationId: uuid()
      .notNull()
      .references(() => automations.id, { onDelete: "cascade" }),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    scheduledFor: timestampTz().notNull(),
    status: automationRunStatusEnum().notNull().default("executing"),
    /** Why a run was skipped or failed, as a policy reason code. */
    reason: text(),
    reasonParams: jsonb().$type<Record<string, string>>(),
    intentId: uuid(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("automation_runs_once_idx").on(table.automationId, table.scheduledFor),
    index("automation_runs_open_idx")
      .on(table.status)
      .where(sql`${table.status} = 'executing'`),
  ],
);

import { Hono } from "hono";
import { z } from "zod";

import { requireAccount } from "../auth/middleware";
import { HTTP, problem } from "../http/problem";
import type { AppEnv } from "../types";
import type { AutomationService } from "./service";

const RECIPIENT_MAX = 80;
const AMOUNT_MAX = 40;
const NOTE_MAX = 140;
const ZONE_MAX = 64;
const MAX_WEEKDAY = 6;
const MAX_MONTHDAY = 28;

const inputSchema = z.object({
  recipient: z.string().min(1).max(RECIPIENT_MAX),
  amount: z.string().max(AMOUNT_MAX),
  asset: z.enum(["USDC", "EURC"]).optional(),
  every: z.enum(["day", "week", "month"]),
  weekday: z.number().int().min(0).max(MAX_WEEKDAY).optional(),
  monthday: z.number().int().min(1).max(MAX_MONTHDAY).optional(),
  time: z.string().regex(/^\d{1,2}:\d{2}$/).optional(),
  timezone: z.string().max(ZONE_MAX).optional(),
  note: z.string().max(NOTE_MAX).nullable().optional(),
});
const activateSchema = z.object({ grantId: z.uuid(), signature: z.string().regex(/^0x[0-9a-fA-F]+$/) });

async function parse<T extends z.ZodType>(schema: T, body: unknown): Promise<z.infer<T>> {
  const parsed = schema.safeParse(body);
  if (!parsed.success) throw problem(HTTP.badRequest, "validation", undefined, { issues: parsed.error.issues });
  return parsed.data;
}

export function automationRoutes(automations: AutomationService) {
  const app = new Hono<AppEnv>();
  // Automations act on the person's money without asking again: accounts only.
  app.use("*", requireAccount);

  app.get("/", async (c) => c.json({ automations: await automations.list(c.get("user")!) }));
  app.post("/", async (c) => {
    const input = await parse(inputSchema, await c.req.json());
    return c.json({ automation: await automations.create(c.get("user")!, input) }, HTTP.created);
  });
  app.get("/:id", async (c) => c.json({ automation: await automations.get(c.get("userId")!, c.req.param("id")) }));
  app.post("/:id/grant", async (c) => c.json(await automations.grantRequest(c.get("user")!, c.req.param("id"))));
  app.post("/:id/activate", async (c) => {
    const input = await parse(activateSchema, await c.req.json());
    return c.json({ automation: await automations.activate(c.get("user")!, c.req.param("id"), { grantId: input.grantId, signature: input.signature as `0x${string}` }) });
  });
  app.post("/:id/pause", async (c) => c.json({ automation: await automations.pause(c.get("user")!, c.req.param("id")) }));
  app.post("/:id/resume", async (c) => c.json({ automation: await automations.resume(c.get("user")!, c.req.param("id")) }));
  app.post("/:id/skip", async (c) => c.json({ automation: await automations.skip(c.get("user")!, c.req.param("id")) }));
  app.post("/:id/cancel", async (c) => c.json(await automations.cancel(c.get("user")!, c.req.param("id"))));
  return app;
}

/** The schedule as asked, completed: 09:00 and the person's own zone when not said; this weekday / day when missing. */
private schedule(user: SessionUser, input: AutomationInput): { schedule: AutomationSchedule; valid: boolean } {
  const timezone = input.timezone && isValidTimeZone(input.timezone) ? input.timezone : isValidTimeZone(user.timezone) ? user.timezone : "UTC";
  const time = input.time && TIME_PATTERN.test(input.time) ? input.time.padStart(TIME_CHARS, "0") : DEFAULT_TIME;
  const today = new Date();
  const schedule: AutomationSchedule = {
    every: input.every,
    time,
    timezone,
    ...(input.every === "week" ? { weekday: input.weekday ?? today.getUTCDay() } : {}),
    ...(input.every === "month" ? { monthday: input.monthday ?? Math.min(today.getUTCDate(), MAX_MONTHDAY) } : {}),
  };
  const valid =
    (input.timezone === undefined || isValidTimeZone(input.timezone)) &&
    (schedule.weekday === undefined || (schedule.weekday >= 0 && schedule.weekday <= MAX_WEEKDAY)) &&
    (schedule.monthday === undefined || (schedule.monthday >= 1 && schedule.monthday <= MAX_MONTHDAY));
  return { schedule, valid };
}

const resolved = resolution.facts.status === "resolved" ? resolution.facts : undefined;
const action: AutomationAction = {
